SELECT c.id, 1, '## 예외 처리 코드
다음은 `@ControllerAdvice`를 사용하여 REST API에서 발생하는 다양한 예외를 처리하는 방법입니다. 이 예시에서는 `NotFoundException`과 `BadRequestException`에 대해 각각 다른 HTTP 상태 코드와 메시지를 반환합니다.
```java
@ControllerAdvice
public class RestExceptionHandler {
    @ExceptionHandler(NotFoundException.class)
    public ResponseEntity<Object> handleNotFoundException(NotFoundException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(BadRequestException.class)
    public ResponseEntity<Object> handleBadRequestException(BadRequestException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST);
    }
}
```
위 코드는 각 예외에 따라 적절한 HTTP 상태 코드와 메시지를 반환하여 클라이언트에게 에러 상황을 명확하게 전달합니다.', '[0.815273,-0.002680,-2.798048,-1.040207,1.771748,-0.377293,0.598044,-0.222407,0.453896,-1.530488,0.024979,0.521761,0.345762,0.335561,0.496889,-0.835152,-0.235217,-0.607790,-1.040065,-0.314599,0.114355,-0.080144,-0.249891,-1.149940,1.289282,0.941012,-0.179645,0.298910,-1.011332,0.248321,0.078751,-0.947468,0.495072,-0.466608,0.074515,0.323607,-0.055239,0.006657,-0.132665,0.592680,0.195641,-0.304388,-0.057185,-0.816960,1.038761,0.090454,1.317598,1.000180,1.251352,-0.836676,0.248886,-1.091713,-0.102168,-1.047163,0.744376,0.432942,-0.383993,0.587868,-1.011431,-1.355245,1.092566,1.583779,-0.186204,1.501090,0.700784,-0.091470,-0.126662,1.254175,-1.020823,0.360237,0.542835,1.000929,-1.019581,0.020122,-1.352434,-0.122063,-0.133000,-1.129458,-0.521654,0.424588,0.146995,-0.089957,0.746870,-0.102168,1.077183,0.977456,-0.979570,0.117351,-0.526549,1.801445,1.223199,-0.613946,0.338654,-0.308727,-1.096800,0.694240,0.428788,1.135829,-1.495576,-0.015383,-0.317992,-0.359718,-0.647694,0.334199,-0.335967,1.077516,-0.073360,0.695550,0.507185,0.240483,0.071041,0.565704,-0.743897,-0.886032,0.919211,-0.549308,0.612017,0.194690,0.223385,0.280996,-0.066875,-0.139912,-0.353885,1.161500,1.289132,0.217516,0.384137,0.476395,0.757132,-0.942584,-0.660327,-0.947128,-0.738633,-0.583325,0.617843,0.203960,-0.972001,0.721914,-0.381671,0.231432,1.202964,0.324690,-0.036632,-0.624069,0.436262,-0.293937,1.320941,-0.158281,-0.920559,0.034259,-0.545586,0.506257,-0.146164,-0.148328,0.013306,-0.469145,-0.216064,-0.229952,0.549456,-0.135722,1.387044,0.816905,0.015999,0.750724,0.062036,-0.461939,-0.692140,1.273271,0.745737,0.203452,-2.079494,0.083206,0.507978,0.140406,-0.018033,0.839178,0.311566,-0.818260,0.162928,-0.537427,-0.433693,-1.658361,0.899988,1.068866,-0.471369,-0.064095,0.258834,-0.583419,-0.613322,-2.023391,0.533495,0.189500,-0.626349,0.106350,-0.913307,-0.600065,0.034330,-1.107555,0.198977,-0.480401,0.771815,-0.318471,0.345518,-0.