SELECT c.id, 0, '# Spring의 트랜잭션 롤백

Spring에서 트랜잭션을 처리할 때, 예외가 발생하면 자동으로 롤백이 되지만, 이러한 자동 롤백은 unchecked 예외에만 적용됩니다. checked 예외는 일반적으로 롤백되지 않으며 개발자가 이를 명시적으로 관리해야 합니다.', '[0.425368,-0.917395,-4.199017,0.289281,0.540526,-0.049958,1.308109,0.608700,-0.419244,-1.750324,-0.780651,1.279539,1.710470,0.360385,-0.392346,-0.774904,-0.024873,-1.329070,-0.770776,0.586605,0.449617,-0.317472,-1.067580,-1.561271,2.431428,0.690319,-0.464738,0.290330,-1.312505,-0.923492,0.213903,-1.514946,0.008491,-0.776910,-1.044000,-0.456052,0.483456,0.554052,0.929894,-0.528040,0.889123,-0.581245,-0.506986,-0.094736,0.778377,-0.154915,1.374150,1.607753,1.937917,-1.282494,0.526915,0.191223,0.148763,-1.117339,0.594510,0.255161,0.243572,-0.100310,0.953347,-0.113010,1.514162,0.622140,-1.174230,0.468902,0.193301,-0.244481,0.623978,-0.049803,0.460105,-0.804477,1.252173,0.555772,-0.146858,0.127685,-0.199701,-0.127188,-0.939412,-0.042211,-0.196218,-0.155806,0.545372,0.108604,1.107683,0.260311,1.770302,1.120320,0.383992,-0.264009,-0.823561,0.762433,0.830366,-0.926388,0.055046,-0.030383,-2.025418,0.572846,0.214200,1.247744,-0.556374,-0.722317,-0.313255,-0.525874,-0.062438,-0.421512,-0.014529,0.701856,-0.248818,0.262397,-1.645195,-0.585279,-1.139042,1.005026,-0.470716,0.014919,0.439920,-0.357030,0.967347,-0.295987,0.686458,0.040601,-0.687372,-0.208255,-0.766842,1.389762,0.437942,0.682575,-0.314788,0.247714,0.231910,-1.852081,-0.156010,0.221480,-0.179059,0.119570,-0.853030,1.266881,-0.438648,0.279826,0.596740,-0.440887,0.158743,0.857597,0.021124,-1.325296,0.976004,-0.197802,0.545137,-0.762277,-1.125591,0.592246,0.298201,0.214534,-0.086904,0.248953,-0.272614,-0.902883,-0.968891,-0.156765,0.028826,0.381721,0.662499,0.417637,-0.512926,0.620119,-0.354873,-1.485560,-0.221638,2.464191,0.040063,0.153370,-1.538308,0.362950,-0.533228,-0.113166,0.500310,-0.714711,0.312675,-0.726086,0.978462,-0.618746,-0.257665,-0.885247,1.151164,0.646708,-1.584645,-1.375641,0.754974,-0.449622,-0.791076,-1.077880,-0.033444,0.622594,-1.152949,-0.528448,-0.218297,-0.231599,0.