SELECT c.id, 0, '# Docker란 무엇인가?

Docker는 애플리케이션을 포팅하기 쉽게 만든 오픈소스 플랫폼입니다. 개발자들은 Docker를 사용하여 코드, 라이브러리, 설정 파일 등을 하나의 패키지로 묶어, 이 패키지를 어떤 환경에서도 동일하게 실행할 수 있습니다.', '[-0.439526,0.582883,-3.124634,0.260242,0.311393,-0.799367,0.255970,-0.030825,-1.545618,-1.254765,-0.410343,1.132934,1.838499,0.550618,0.756835,-0.864733,-0.789348,-1.282704,-0.774794,1.585508,-0.653907,-0.588797,-1.267892,-1.534976,1.844297,0.994630,0.673587,0.602539,-1.479152,-0.603276,0.093311,-1.210082,0.046554,-2.285280,-0.996390,-1.378291,-0.009748,0.277030,0.981282,-0.058990,-0.333836,-0.432058,-0.482246,-0.877481,0.092754,0.298124,0.479167,0.004512,1.493086,-1.395501,0.714134,-0.582933,-0.401211,-2.698267,0.006191,1.149245,-0.863797,0.110906,-0.169743,0.163715,0.944667,1.246983,-0.240871,2.457845,1.182976,0.052539,1.094090,1.168569,-0.033466,-0.410071,1.757157,1.235390,-0.028940,0.551067,0.636444,0.350444,-1.107396,-0.132313,-0.396249,0.759182,0.845951,-0.396411,2.293082,0.198927,1.268740,0.618037,-0.807410,-0.047562,-1.321904,0.238171,0.428758,-0.454750,0.245387,0.554982,-2.052967,0.564618,0.403461,1.028283,-0.953840,-0.994692,-0.125681,-0.521092,0.745107,-0.136686,0.579314,1.803310,0.129045,0.698759,-0.283381,-0.798662,-1.057578,0.687474,-0.415974,0.448252,0.236327,-0.931204,1.084494,-0.490304,0.336665,0.181924,-0.115322,0.439079,-0.015744,1.368217,1.393632,0.864060,-0.426550,0.313299,0.268416,-0.849773,0.325783,-0.314886,-1.278062,-0.681218,-0.336141,0.874471,-0.977068,0.682257,0.671850,0.145995,-0.074832,0.644400,0.309689,-1.403011,-1.032772,-0.664863,1.193089,0.072718,-1.682976,1.089565,-0.030895,-0.083517,0.021164,0.497415,0.038589,-0.665347,-0.548478,0.320439,0.782061,0.153469,0.898723,0.510416,-0.429151,0.716844,-0.088025,-0.865412,0.773637,1.021251,-0.573800,0.327672,-1.621619,-1.205379,-0.584211,0.586785,-0.323544,-0.301836,-0.206722,-0.778366,0.508212,0.009399,0.171868,-0.563940,2.026397,-0.070790,-1.536856,-0.801172,-0.052252,-0.440000,-0.561321,-0.238626,0.158031,1.923945,-0.171358,0.284929,-0.652680,-0.081792,0.864763,-